query StatsGetGolfTournamentStats($input: GetGolfTournamentStatsInput!) {
  getGolfTournamentStats(input: $input) {
    category
    fieldAvgs {
      subCat
      total
      rounds {
        average
        percentage
        round
      }
    }
    subCats {
      subCat
      ...GolfStatRanking
    }
  }
}

fragment GolfStatRanking on GolfStatSubCatDetails {
  rankings {
    teamId
    players {
      id
      lastName
      firstName
      country
    }
    rounds {
      round
      rank
      total
      divisor
      average
      percentile
    }
    total {
      total
      divisor
      rank
      average
      percentile
    }
  }
}
